From a7a8a7c2d536f18960613d16c7c9673092aaaac1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:49:49 +0100
Subject: [PATCH] activitymanager: freeze the activity order on the first
 Meta+A press

The switcher only froze the most-recently-used order once it decided to
show itself, so the first switch already reordered the list and saved
its time, sending later presses back. Freeze it on the keypress instead.

BUG: 419499
---
 imports/activitymanager/switcherbackend.cpp | 13 ++++++++-----
 1 file changed, 8 insertions(+), 5 deletions(-)

diff --git a/imports/activitymanager/switcherbackend.cpp b/imports/activitymanager/switcherbackend.cpp
index 3744bc1fe2..989e9c79c3 100644
--- a/imports/activitymanager/switcherbackend.cpp
+++ b/imports/activitymanager/switcherbackend.cpp
@@ -184,8 +184,6 @@ SwitcherBackend::SwitcherBackend(QObject *parent)
                      Qt::META | Qt::SHIFT | Qt::Key_A,
                      &SwitcherBackend::keybdSwitchToPreviousActivity);

-    connect(this, &SwitcherBackend::shouldShowSwitcherChanged, m_runningActivitiesModel, &SortedActivitiesModel::setInhibitUpdates);
-
     m_modKeyPollingTimer.setInterval(100);
     connect(&m_modKeyPollingTimer, &QTimer::timeout, this, &SwitcherBackend::showActivitySwitcherIfNeeded);

@@ -250,6 +248,7 @@ void SwitcherBackend::switchToActivity(Direction direction)
 void SwitcherBackend::keybdSwitchedToAnotherActivity()
 {
     m_lastInvokedAction = dynamic_cast<QAction *>(sender());
+    m_runningActivitiesModel->setInhibitUpdates(true);
     QTimer::singleShot(100, this, &SwitcherBackend::showActivitySwitcherIfNeeded);
 }

@@ -281,7 +280,7 @@ void SwitcherBackend::init()

 void SwitcherBackend::onCurrentActivityChanged(const QString &id)
 {
-    if (m_shouldShowSwitcher) {
+    if (m_runningActivitiesModel->inhibitUpdates()) {
         // If we are showing the switcher because the user is
         // pressing Meta+Tab, we are not ready to commit the
         // activity change to memory
@@ -323,10 +322,12 @@ bool SwitcherBackend::shouldShowSwitcher() const

 void SwitcherBackend::setShouldShowSwitcher(bool shouldShowSwitcher)
 {
-    if (m_shouldShowSwitcher == shouldShowSwitcher)
+    if (m_shouldShowSwitcher == shouldShowSwitcher && m_runningActivitiesModel->inhibitUpdates() == shouldShowSwitcher)
         return;

+    const bool changed = m_shouldShowSwitcher != shouldShowSwitcher;
     m_shouldShowSwitcher = shouldShowSwitcher;
+    m_runningActivitiesModel->setInhibitUpdates(m_shouldShowSwitcher);

     if (m_shouldShowSwitcher) {
         // TODO: We really should NOT do this by polling
@@ -338,7 +339,9 @@ void SwitcherBackend::setShouldShowSwitcher(bool shouldShowSwitcher)
         onCurrentActivityChanged(m_activities.currentActivity());
     }

-    Q_EMIT shouldShowSwitcherChanged(m_shouldShowSwitcher);
+    if (changed) {
+        Q_EMIT shouldShowSwitcherChanged(m_shouldShowSwitcher);
+    }
 }

 QAbstractItemModel *SwitcherBackend::runningActivitiesModel() const
